<?php require_once __DIR__.'/config.php';$u=require_login();$cats=data_load('categories.json');$cat=(int)($_GET['category']??0);$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$title=trim($_POST['title']??'');$content=trim($_POST['content']??'');$cat=(int)($_POST['category_id']??0);if(strlen($title)<3||strlen($content)<3)$err='Заполните заголовок и текст.';else{$threads=data_load('threads.json');$threads[]=['id'=>count($threads)+1,'category_id'=>$cat,'title'=>$title,'content'=>$content,'author'=>$u['username'],'created_at'=>date('c')];data_save('threads.json',$threads);header('Location:thread.php?id='.end($threads)['id']);exit;}}?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Новая тема — GREFFRLEND</title><link rel="stylesheet" href="style.css"></head><body><main class="wrap"><div class="card form" style="margin:50px auto"><a class="logo" href="index.php">GREFFRLEND</a><h1>Новая тема</h1><?php if($err):?><div class="card danger"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Раздел</label><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach;?></select><label>Заголовок</label><input name="title" required><label>Текст</label><textarea name="content" required></textarea><button class="btn">Опубликовать</button></form></div></main></body></html>